    ) {
        UserAccount user = requestAuthorizationService.requireAnyRole(token, SecurityConstants.ROLE_MODERATOR, SecurityConstants.ROLE_ORG_ADMIN, SecurityConstants.ROLE_PLATFORM_ADMIN);
